import hashlib

class RefundBackend:
    def __init__(self):
        self.total_disbursed = 0
        self.idempotency_ledger = {}
        self.network_attempts = 0

    def issue_refund(self, order_id, amount, idempotency_key=None):
        self.network_attempts += 1
        if idempotency_key is not None and idempotency_key in self.idempotency_ledger:
            return self.idempotency_ledger[idempotency_key]

        # Server commits the mutation BEFORE network response travels back!
        self.total_disbursed += amount
        receipt = {"order_id": order_id, "amount": amount, "status": "COMMITTED"}
        if idempotency_key is not None:
            self.idempotency_ledger[idempotency_key] = receipt

        if self.network_attempts == 1:
            raise TimeoutError("504 Gateway Timeout on return path")
        return receipt

# Case 1: Naive agent retries on timeout without idempotency key -> DOUBLE REFUND!
naive_api = RefundBackend()
for attempt in range(2):
    try:
        naive_api.issue_refund("ORD-77", 1500)
        break
    except TimeoutError:
        pass

# Case 2: Production agent attaches deterministic session+turn+args idempotency key
safe_api = RefundBackend()
idem_key = hashlib.sha256(b"sess_42|turn_3|ORD-77|1500").hexdigest()[:16]
res = None
for attempt in range(2):
    try:
        res = safe_api.issue_refund("ORD-77", 1500, idempotency_key=idem_key)
        break
    except TimeoutError:
        pass

# Multi-step compounding reliability & ReAct O(M^2) prefill cost (M=10, p=0.92)
m_steps = 10
p_step = 0.92
p_task_r1 = p_step ** m_steps
p_task_r2 = (1.0 - (1.0 - p_step) ** 2) ** m_steps
c_react = 0
for k in range(1, m_steps + 1):
    c_react += 1000 + k * 400

print(f"Naive disbursed: {naive_api.total_disbursed} | Safe disbursed: {safe_api.total_disbursed} | Status: {res['status']}")
print(f"10-step P_task: R=1 -> {p_task_r1:.4f} | R=2 -> {p_task_r2:.4f} | ReAct Prefill={c_react:,} tokens")

assert naive_api.total_disbursed == 3000 and safe_api.total_disbursed == 1500
